import{c as e,d as t,h as n,k as r,m as i,t as a,vt as o}from"./chunks/plugin-vue_export-helper.sM-KdTqA.js";const s=JSON.parse(`{"title":"可视化画布与页面管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/canvas-and-pages.md","filePath":"zh/guide/canvas-and-pages.md"}`);var c={name:`zh/guide/canvas-and-pages.md`};function l(a,s,c,l,u,d){return r(),t(`div`,null,[s[9]||=i(`<h1 id="可视化画布与页面管理" tabindex="-1">可视化画布与页面管理 <a class="header-anchor" href="#可视化画布与页面管理" aria-label="Permalink to “可视化画布与页面管理”">​</a></h1><p>本章详细介绍如何在 QC Flutter Flow 中管理多页面应用结构、使用可视化画布进行精准排版、适配手机/平板/桌面多端屏幕，以及配置组件的四象限属性。</p><hr><h2 id="一、页面与分组管理" tabindex="-1">一、页面与分组管理 <a class="header-anchor" href="#一、页面与分组管理" aria-label="Permalink to “一、页面与分组管理”">​</a></h2><p>在左侧面板点击 <strong>「页面」</strong> 图标，即可管理整个应用的所有页面、路由分组与局部复用组件。</p><h3 id="_1-页面分组与自动路由" tabindex="-1">1. 页面分组与自动路由 <a class="header-anchor" href="#_1-页面分组与自动路由" aria-label="Permalink to “1. 页面分组与自动路由”">​</a></h3><p>平台采用 <strong>「分组 + 页面」</strong> 的两级管理模式，无需手动编写复杂的路由表配置文件：</p><table tabindex="0"><thead><tr><th style="text-align:left;">分组类型</th><th style="text-align:left;">默认标识</th><th style="text-align:left;">用途说明</th><th style="text-align:left;">自动生成的路由路径示例</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>启动组</strong></td><td style="text-align:left;"><code>group_startup</code></td><td style="text-align:left;">存放应用启动页或主框架页</td><td style="text-align:left;"><code>/startup/main</code></td></tr><tr><td style="text-align:left;"><strong>业务分组</strong></td><td style="text-align:left;">自定义（如 <code>user</code>、<code>shop</code>）</td><td style="text-align:left;">按业务模块归类页面（如登录注册、商品模块）</td><td style="text-align:left;"><code>/user/login</code>、<code>/shop/detail</code></td></tr><tr><td style="text-align:left;"><strong>局部组件组</strong></td><td style="text-align:left;"><code>group_local</code></td><td style="text-align:left;">存放可在多个页面复用的局部组件（如商品卡片、自定义弹窗）</td><td style="text-align:left;">不生成独立路由，供页面引用或弹窗调用</td></tr><tr><td style="text-align:left;"><strong>全局配置</strong></td><td style="text-align:left;"><code>group_global_config</code></td><td style="text-align:left;">管理全局状态变量、全局主题色与网络通道配置</td><td style="text-align:left;">全局生效</td></tr></tbody></table><h3 id="_2-页面常用操作" tabindex="-1">2. 页面常用操作 <a class="header-anchor" href="#_2-页面常用操作" aria-label="Permalink to “2. 页面常用操作”">​</a></h3><ul><li><strong>新建分组</strong>：点击页面面板顶部的 <strong>「+ 新建分组」</strong>，输入分组名称（如 <code>订单模块</code>）。</li><li><strong>新建页面</strong>：点击目标分组右侧的 <strong>「+」</strong> 号，可选择创建： <ul><li><strong>空白页面</strong>：带标准页面脚手架（Scaffold）的全新页面。</li><li><strong>预设模板页</strong>：从内置行业模板快速创建。</li><li><strong>局部复用组件</strong>：创建独立的局部组件画板，可在其它页面通过「页面引用」组件嵌入，或通过 <code>系统_弹出组件(&quot;组件名&quot;)</code> 弹窗展示。</li></ul></li><li><strong>复制页面</strong>：在任意页面条目上点击鼠标右键 -&gt; 选择 <strong>「复制页面」</strong>，系统会完整克隆该页面的组件树与交互代码。</li><li><strong>删除页面保护</strong>：右键选择 <strong>「删除」</strong> 可移除页面。平台内置了防死锁保护机制——不允许删光所有业务页面，确保工程始终保有至少一个可启动的主页面。</li></ul><hr><h2 id="二、画布排版与容器插槽用法" tabindex="-1">二、画布排版与容器插槽用法 <a class="header-anchor" href="#二、画布排版与容器插槽用法" aria-label="Permalink to “二、画布排版与容器插槽用法”">​</a></h2><h3 id="_1-页面脚手架-scaffold-的五大插槽" tabindex="-1">1. 页面脚手架（Scaffold）的五大插槽 <a class="header-anchor" href="#_1-页面脚手架-scaffold-的五大插槽" aria-label="Permalink to “1. 页面脚手架（Scaffold）的五大插槽”">​</a></h3><p>每个标准页面最外层都是一个 <strong>「页面脚手架 (Scaffold)」</strong>，它提供了 5 个专属插槽区域。将组件拖入对应区域即可自动完成页面结构装配：</p><ul><li><strong><code>appBar</code>（顶部导航栏插槽）</strong>：放置「顶部导航栏 (AppBar)」或「搜索栏 (SearchBar)」。</li><li><strong><code>body</code>（页面主体插槽）</strong>：放置页面核心内容（通常先放入一个 <code>纵向容器 Column</code>、<code>列表视图 ListView</code> 或 <code>下拉刷新容器 RefreshContainer</code>）。</li><li><strong><code>bottomNavigationBar</code>（底部栏插槽）</strong>：放置「底部导航栏 (BottomNavBar)」或电商详情页常用的「底部操作栏 (BottomActionBar)」。</li><li><strong><code>floatingActionButton</code>（悬浮按钮插槽）</strong>：放置右下角「悬浮按钮 (FAB)」或「悬浮菜单 (FabMenu)」。</li><li><strong><code>drawer</code>（侧边抽屉插槽）</strong>：放置「侧边抽屉菜单 (DrawerMenu)」，可通过 <code>打开左侧菜单()</code> 函数呼出。</li></ul><h3 id="_2-常用布局容器选择指南" tabindex="-1">2. 常用布局容器选择指南 <a class="header-anchor" href="#_2-常用布局容器选择指南" aria-label="Permalink to “2. 常用布局容器选择指南”">​</a></h3><p>在画布中排版时，合理组合容器可以实现任意复杂的界面布局：</p><table tabindex="0"><thead><tr><th style="text-align:left;">你想实现的排版效果</th><th style="text-align:left;">推荐使用的容器组件</th><th style="text-align:left;">使用技巧</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>从上到下垂直排列</strong></td><td style="text-align:left;"><strong>纵向容器 (<code>Column</code>)</strong></td><td style="text-align:left;">在右侧「布局」面板设置 <code>spacing</code>（子项间距）和对齐方式；若内容超出一屏，可在属性中开启滚动模式。</td></tr><tr><td style="text-align:left;"><strong>从左到右水平排列</strong></td><td style="text-align:left;"><strong>横向容器 (<code>Row</code>)</strong></td><td style="text-align:left;">适合做图文并排、左右两端对齐（将主轴对齐设为 <code>spaceBetween</code>）。</td></tr><tr><td style="text-align:left;"><strong>多个元素重叠（如图片上叠文字角标）</strong></td><td style="text-align:left;"><strong>层叠容器 (<code>Stack</code>)</strong></td><td style="text-align:left;">子组件可以直接在画布上拖拽位置（调整 <code>x</code>、<code>y</code> 坐标）实现多层叠加。</td></tr><tr><td style="text-align:left;"><strong>加背景色、圆角、边框、阴影或内边距</strong></td><td style="text-align:left;"><strong>通用容器 (<code>Container</code>)</strong> / <strong>卡片 (<code>Card</code>)</strong></td><td style="text-align:left;">单子节点容器，专门用来做视觉装饰、留白间距或固定宽高。</td></tr><tr><td style="text-align:left;"><strong>横向滑动标签或商品栏</strong></td><td style="text-align:left;"><strong>横向滚动 (<code>HScroll</code>)</strong></td><td style="text-align:left;">内部放入多个卡片或标签即可直接左右滑动。</td></tr><tr><td style="text-align:left;"><strong>自动换行的标签组/热搜词</strong></td><td style="text-align:left;"><strong>流式换行 (<code>WrapLayout</code>)</strong></td><td style="text-align:left;">子项排满一行后自动折行到下一行。</td></tr><tr><td style="text-align:left;"><strong>响应式多列网格布局</strong></td><td style="text-align:left;"><strong>栅格行 (<code>GridRow</code>) + 栅格列 (<code>GridCol</code>)</strong></td><td style="text-align:left;">按栅格比例分配列宽，适合仪表盘与后台表单排版。</td></tr></tbody></table><h3 id="_3-组件树定位与画布操作技巧" tabindex="-1">3. 组件树定位与画布操作技巧 <a class="header-anchor" href="#_3-组件树定位与画布操作技巧" aria-label="Permalink to “3. 组件树定位与画布操作技巧”">​</a></h3><ul><li><strong>组件树自动居中定位</strong>：当页面组件层级较深、在画布上不好点选时，直接在左侧 <strong>「组件树」</strong> 面板点击节点名称，或者在画布点击组件，左侧组件树都会自动展开并平滑滚动到视口正中央。</li><li><strong>框选与编组</strong>：按住 <code>Shift</code> 键在画布上拖拽框选多个同级组件，点击鼠标右键选择 <strong>「组合为容器 (Row / Column / Container)」</strong>，即可一键将它们打包进同一个父容器中。</li><li><strong>实时尺寸拉伸</strong>：选中画布上的组件后，拖拽蓝色高亮框四周的控制手柄即可直观调整宽高。</li><li><strong>画布异常一键恢复</strong>：如果不小心设置了冲突的宽高约束导致组件渲染报错，画布不会崩溃卡死，而是会显示一张友好的异常提示卡，点击卡片上的 <strong>「一键撤销上一步」</strong> 即可立即恢复正常。</li></ul><hr><h2 id="三、多端响应式断点设计" tabindex="-1">三、多端响应式断点设计 <a class="header-anchor" href="#三、多端响应式断点设计" aria-label="Permalink to “三、多端响应式断点设计”">​</a></h2><p>同一个页面如何同时适配手机、平板和电脑大屏？QC Flutter Flow 支持<strong>三端断点独立样式覆盖</strong>：</p><ol><li>在顶部工具栏点击切换视口断点： <ul><li><strong>📱 手机端 (Mobile)</strong>：<code>375 × 812</code>（默认基准视口）</li><li><strong>📟 平板端 (Tablet)</strong>：<code>768 × 1024</code></li><li><strong>💻 桌面端 (Desktop)</strong>：<code>1440 × 900</code></li></ul></li><li>当你切换到 <strong>平板</strong> 或 <strong>桌面</strong> 视口后，在右侧属性面板修改某个组件的<strong>宽度、高度、内外边距、背景色、渐变、圆角或边框</strong>时，这些修改只会记录在当前断点下，不会破坏手机端的默认排版。</li><li>应用在真机或浏览器运行时，会根据当前屏幕宽度自动切换到对应断点的样式；若某属性在平板/桌面端未单独设置，则自动继承手机端的默认属性。</li></ol><hr><h2 id="四、四象限属性检查器与主题色彩系统" tabindex="-1">四、四象限属性检查器与主题色彩系统 <a class="header-anchor" href="#四、四象限属性检查器与主题色彩系统" aria-label="Permalink to “四、四象限属性检查器与主题色彩系统”">​</a></h2><p>在画布中选中任意组件后，右侧 <strong>「属性检查器」</strong> 分为四个标签象限：</p><h3 id="_1-四大属性象限" tabindex="-1">1. 四大属性象限 <a class="header-anchor" href="#_1-四大属性象限" aria-label="Permalink to “1. 四大属性象限”">​</a></h3>`,28),e(`ul`,null,[s[7]||=i(`<li><strong>外观 (Appearance)</strong>： <ul><li><strong>尺寸</strong>：宽度、高度（支持输入具体像素值、百分比或设为自适应/撑满）。</li><li><strong>边距</strong>：内边距 (<code>Padding</code>) 与外边距 (<code>Margin</code>)，支持上下左右四方向独立设置。</li><li><strong>装饰</strong>：背景颜色、线性/径向渐变色、边框粗细与颜色、四个角独立的圆角半径、阴影效果与透明度 (<code>Opacity</code>)。</li></ul></li>`,1),e(`li`,null,[s[5]||=e(`strong`,null,`内容 (Content)`,-1),s[6]||=n(`： `,-1),e(`ul`,null,[s[3]||=e(`li`,null,`配置组件特有的业务属性（如文本内容、字号、输入框占位符、开关默认状态）。`,-1),s[4]||=e(`li`,null,[e(`strong`,null,`三合一媒体选择器`),n(`：点击图标或图片属性时，可在弹窗中直接选择 `),e(`strong`,null,`Material 图标、Cupertino 图标、网络图片 URL 或本地项目资源图片`),n(`。`)],-1),e(`li`,null,[s[0]||=e(`strong`,null,`数据绑定`,-1),s[1]||=n(`：点击属性右侧的绑定按钮（或直接输入 `,-1),e(`code`,null,o(a.变量名),1),s[2]||=n(`），即可将组件内容与动态状态变量关联。`,-1)])])]),s[8]||=i(`<li><strong>事件 (Events)</strong>： <ul><li>为组件绑定交互动作，如 <strong>点击 (<code>onTap</code>)、双击、长按、鼠标悬浮 (<code>onHover</code>)、值改变 (<code>onChanged</code>)、提交 (<code>onSubmitted</code>)、下拉刷新 (<code>onRefresh</code>)</strong> 等。</li></ul></li><li><strong>布局 (Layout)</strong>： <ul><li>配置弹性权重 (<code>flex</code>)、主轴对齐 (<code>mainAxisAlignment</code>)、交叉轴对齐 (<code>crossAxisAlignment</code>)、子元素间距 (<code>spacing</code>) 以及条件显隐 (<code>visible</code>)。</li></ul></li>`,2)]),s[10]||=i(`<h3 id="_2-10-大内置语义色彩-token-自动适配亮-暗黑模式" tabindex="-1">2. 10 大内置语义色彩 Token（自动适配亮/暗黑模式） <a class="header-anchor" href="#_2-10-大内置语义色彩-token-自动适配亮-暗黑模式" aria-label="Permalink to “2. 10 大内置语义色彩 Token（自动适配亮/暗黑模式）”">​</a></h3><p>在设置组件颜色时，除了直接输入十六进制色值（如 <code>#FF6B00</code>），<strong>强烈推荐使用平台内置的 10 大语义色彩 Token</strong>。使用语义色后，当应用调用 <code>切换主题模式()</code> 切换到暗黑模式时，所有界面颜色会自动平滑切换，无需手动写两套样式：</p><table tabindex="0"><thead><tr><th style="text-align:left;">色彩名称</th><th style="text-align:left;">代码与属性写法</th><th style="text-align:center;">浅色模式默认色</th><th style="text-align:center;">深色模式默认色</th><th style="text-align:left;">推荐用途</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>主品牌色</strong></td><td style="text-align:left;"><code>QcColor.primary</code></td><td style="text-align:center;"><code>#2563EB</code></td><td style="text-align:center;"><code>#3B82F6</code></td><td style="text-align:left;">主操作按钮、激活态图标、高亮边框、开关选中色</td></tr><tr><td style="text-align:left;"><strong>页面底色</strong></td><td style="text-align:left;"><code>QcColor.background</code></td><td style="text-align:center;"><code>#F8FAFC</code></td><td style="text-align:center;"><code>#0F172A</code></td><td style="text-align:left;">页面脚手架整体大背景</td></tr><tr><td style="text-align:left;"><strong>容器表面色</strong></td><td style="text-align:left;"><code>QcColor.surface</code></td><td style="text-align:center;"><code>#FFFFFF</code></td><td style="text-align:center;"><code>#1E293B</code></td><td style="text-align:left;">卡片底色、弹窗背景、顶部/底部导航栏背景</td></tr><tr><td style="text-align:left;"><strong>主要文字色</strong></td><td style="text-align:left;"><code>QcColor.textMain</code></td><td style="text-align:center;"><code>#0F172A</code></td><td style="text-align:center;"><code>#F8FAFC</code></td><td style="text-align:left;">页面大标题、正文内容、重要数值</td></tr><tr><td style="text-align:left;"><strong>次要文字色</strong></td><td style="text-align:left;"><code>QcColor.textSub</code></td><td style="text-align:center;"><code>#64748B</code></td><td style="text-align:center;"><code>#94A3B8</code></td><td style="text-align:left;">副标题、辅助说明、占位提示词、时间戳</td></tr><tr><td style="text-align:left;"><strong>分割边框色</strong></td><td style="text-align:left;"><code>QcColor.border</code></td><td style="text-align:center;"><code>#E2E8F0</code></td><td style="text-align:center;"><code>#334155</code></td><td style="text-align:left;">输入框边框、列表分割线、卡片外框</td></tr><tr><td style="text-align:left;"><strong>禁用状态色</strong></td><td style="text-align:left;"><code>QcColor.disable</code></td><td style="text-align:center;"><code>#CBD5E1</code></td><td style="text-align:center;"><code>#475569</code></td><td style="text-align:left;">不可点击按钮背景、禁用文字与置灰图标</td></tr><tr><td style="text-align:left;"><strong>成功状态色</strong></td><td style="text-align:left;"><code>QcColor.success</code></td><td style="text-align:center;"><code>#10B981</code></td><td style="text-align:center;"><code>#34D399</code></td><td style="text-align:left;">审核通过、支付成功、正向增长徽标</td></tr><tr><td style="text-align:left;"><strong>警告状态色</strong></td><td style="text-align:left;"><code>QcColor.warning</code></td><td style="text-align:center;"><code>#F59E0B</code></td><td style="text-align:center;"><code>#FBBF24</code></td><td style="text-align:left;">待处理提醒、库存预警、中风险提示</td></tr><tr><td style="text-align:left;"><strong>危险状态色</strong></td><td style="text-align:left;"><code>QcColor.danger</code></td><td style="text-align:center;"><code>#EF4444</code></td><td style="text-align:center;"><code>#F87171</code></td><td style="text-align:left;">删除按钮、表单报错文字、异常警告</td></tr></tbody></table>`,3)])}var u=a(c,[[`render`,l]]);export{s as __pageData,u as default};